Structure(Unit host) {
    this.host = host;
    this.units.add(host);
    this.units.addAll(host.getAllSlaves());
    for (Unit unit : this.units) {
        this.scales.put(unit.getName(), Float.valueOf(unit.getScale()));
    }
}
